namespace {
GLuint vertex_program(){const auto source=mtoon_renderer_vertex(false);const auto *s=source.c_str();GLuint shader=glCreateShader(GL_VERTEX_SHADER);glShaderSource(shader,1,&s,nullptr);glCompileShader(shader);GLint ok=0;glGetShaderiv(shader,GL_COMPILE_STATUS,&ok);if(!ok)throw std::runtime_error("Actual production before vertex shader failed compile");GLuint p=glCreateProgram();glAttachShader(p,shader);const char *varyings[]={"world","source_n","source_t","source_b"};glTransformFeedbackVaryings(p,4,varyings,GL_INTERLEAVED_ATTRIBS);glLinkProgram(p);glDeleteShader(shader);glGetProgramiv(p,GL_LINK_STATUS,&ok);if(!ok)throw std::runtime_error("Actual production vertex feedback failed link");return p;}
struct Columns {std::vector<Vec3> positions,normals;std::vector<std::array<float,4>> tangents;};
Columns before_columns(const MeshSnapshot&s,uint64_t id){const auto range=std::find_if(s.ranges.begin(),s.ranges.end(),[&](const auto&r){return r.object==id;});if(range==s.ranges.end()||!range->source_frame)throw std::runtime_error("Actual source frame snapshot unavailable");Columns out;for(size_t c=0;c<range->count;++c){const size_t logical=range->paint_winding_reversed?c/3*3+(c%3==1?2:c%3==2?1:0):c;const auto v=s.mesh.indices.at(range->first+logical);out.positions.push_back(s.mesh.positions.at(v));out.normals.push_back(s.source_normals.at(v));out.tangents.push_back(s.source_tangents.at(v));}return out;}
std::vector<std::array<Vec3,4>> before_gpu(GLuint program,const Columns &c,const detail::VertexStageMatrices&m,detail::VertexBitangentPolicy policy){struct V{Vec3 p,n;std::array<float,4>t;};std::vector<V> vertices;for(size_t i=0;i<c.positions.size();++i)vertices.push_back({c.positions[i],c.normals[i],c.tangents[i]});GLuint vao=0,buffer=0,feedback=0;glGenVertexArrays(1,&vao);glBindVertexArray(vao);glGenBuffers(1,&buffer);glBindBuffer(GL_ARRAY_BUFFER,buffer);glBufferData(GL_ARRAY_BUFFER,vertices.size()*sizeof(V),vertices.data(),GL_STATIC_DRAW);for(auto [location,count,offset]:{std::tuple{0,3,offsetof(V,p)},std::tuple{7,3,offsetof(V,n)},std::tuple{8,4,offsetof(V,t)}}){glVertexAttribPointer(location,count,GL_FLOAT,GL_FALSE,sizeof(V),reinterpret_cast<void*>(offset));glEnableVertexAttribArray(location);}std::vector<std::array<Vec3,4>> values(c.positions.size());glGenBuffers(1,&feedback);glBindBuffer(GL_TRANSFORM_FEEDBACK_BUFFER,feedback);glBufferData(GL_TRANSFORM_FEEDBACK_BUFFER,values.size()*sizeof(values[0]),nullptr,GL_STREAM_READ);glBindBufferBase(GL_TRANSFORM_FEEDBACK_BUFFER,0,feedback);glUseProgram(program);glUniformMatrix4fv(glGetUniformLocation(program,"model"),1,GL_FALSE,m.model.data());glUniformMatrix4fv(glGetUniformLocation(program,"mvp"),1,GL_FALSE,m.model.data());glUniformMatrix3fv(glGetUniformLocation(program,"normal_model"),1,GL_FALSE,m.normal.data());glUniform1i(glGetUniformLocation(program,"affine_motion"),1);glUniform1i(glGetUniformLocation(program,"source_frame"),1);glUniform1i(glGetUniformLocation(program,"canonical_frame"),0);glUniform1i(glGetUniformLocation(program,"prepared_pbr_frame"),policy==detail::VertexBitangentPolicy::UnitCross);glUniform1f(glGetUniformLocation(program,"model_hand"),m.hand);glEnable(GL_RASTERIZER_DISCARD);glBeginTransformFeedback(GL_POINTS);glDrawArrays(GL_POINTS,0,GLsizei(vertices.size()));glEndTransformFeedback();glDisable(GL_RASTERIZER_DISCARD);glGetBufferSubData(GL_TRANSFORM_FEEDBACK_BUFFER,0,values.size()*sizeof(values[0]),values.data());glBindBufferBase(GL_TRANSFORM_FEEDBACK_BUFFER,0,0);glDeleteBuffers(1,&feedback);glDeleteBuffers(1,&buffer);glDeleteVertexArrays(1,&vao);return values;}
}
int main(int argc,char**argv)try{
 if(argc!=2)return 2;NativeGraphics graphics;const auto source=Scene::load(argv[1]);const auto original=source.encode();const auto refinement=detail::refine_reflected_key(source.active().painted->mesh_owner(),detail::KeyMirrorPlane{0},.0001f);const auto program=vertex_program();double maximum=0,wrong=0;size_t cases=0;
 for(int placement=0;placement<3;++placement)for(float weight:{0.f,.35f,1.f}){auto scene=source;auto &object=scene.active();auto model=*object.deformation;model.morph_weights.assign(model.morphs->targets.size(),weight);scene.set_deformation(object.id,model);if(placement){auto a=AffineTransform{}.matrix();a[0]=placement==2?-1.2:1.2;a[5]=.8;a[10]=1.3;a[4]=.17;a[8]=-.11;a[12]=.03;object.affine_edit=std::make_shared<const NativeAffineEdit>(AffineTransform(a));auto group=scene.add_group("Actual before vertex group");auto g=AffineTransform{}.matrix();g[5]=1.1;g[9]=.13;g[13]=-.02;scene.group(group).affine_edit=std::make_shared<const NativeAffineEdit>(AffineTransform(g));object.group=group;}Document doc;doc.replace(scene);doc.shading(false);settled(doc);const auto frame=doc.frame().surface;const auto columns=before_columns(*frame,scene.active().id);
  for(int held=0;held<3;++held){auto matrix=AffineTransform{}.matrix();if(held){matrix[0]=held==2?-1.1:1.1;matrix[5]=.75;matrix[10]=1.4;matrix[4]=.21;matrix[8]=-.08;matrix[12]=.04;}const auto uniforms=detail::vertex_stage_affine(AffineTransform(matrix));for(auto policy:{detail::VertexBitangentPolicy::RawCross,detail::VertexBitangentPolicy::UnitCross}){auto field=detail::pullback_vertex_stage(refinement,{columns.positions,columns.normals,columns.tangents},uniforms,policy);const auto gpu=before_gpu(program,columns,uniforms,policy);for(size_t c=0;c<refinement.corners.size();++c){const auto &p=refinement.corners[c].current;std::array<Vec3,4> actual{};for(size_t k=0;k<3;++k)for(size_t v=0;v<4;++v)actual[v]+=gpu[p.triangle*3+k][v]*float(p.barycentric[k]);maximum=std::max({maximum,double(length(actual[0]-field.positions[c])),double(length(actual[1]-field.normals[c])),double(length(actual[2]-field.tangents[c])),double(length(actual[3]-field.bitangents[c]))});wrong=std::max(wrong,double(length(cross(field.normals[c],field.tangents[c])*columns.tangents[p.triangle*3][3]*uniforms.hand-field.bitangents[c])));}check(maximum<=1e-6,"Actual original production VS pullback preserves world/N/T/B through morph/group/full-affine/held transforms");++cases;}}
 }
 glDeleteProgram(program);std::cout<<"ACTUAL_VERTEX_PULLBACK cases="<<cases<<" maximum="<<maximum<<" recomputed_B_error="<<wrong<<std::endl;check(wrong>1e-4,"Independent bitangent field is sensitive to incorrect cross of interpolated normal/tangent");check(source.encode()==original,"Before vertex pipeline proof preserves complete actual canonical/F32 source");std::cout<<"PASS "<<checks<<" actual before vertex pipeline checks\n";return 0;
}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}
